import { within } from 'storybook/test';
import { html } from 'lit';
import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import comp from './main.js';
import defaultArgs from './previews/default.data.json';
import withWhatIsThisLinkArgs from './previews/with-what-is-this-link.data.json';

const squiz = squizStoryRenderer(comp.main);

/**
 * The component is position:fixed, so it contributes no height to normal
 * document flow. Storybook's docs canvas auto-sizes each story by measuring
 * that flow height, so without this wrapper it renders as a near-0px box
 * and the fixed banner gets clipped/scrolled instead of shown in full.
 */
function withPageContent(input) {
  return html`
    <div style="padding-block-start: 140px; min-height: 260px;">
      ${squiz(input)}
      <div style="max-width: 800px; margin: 0 auto; padding: 24px;">
        <p>This preview simulates page content behind the fixed banner above, so the docs canvas has enough height to show it in full.</p>
      </div>
    </div>
  `;
}

function supressClickEvent(event) {
  event.preventDefault();
  event.stopPropagation();
  alert('This is a preview only: activating the banner in this Storybook will not navigate the browser to the exit URL.');
}
async function suppressClick() {
  const qes = [...document.querySelectorAll('.quick-exit')];
  qes.forEach(qe => {
    qe.removeEventListener('click', supressClickEvent);
    qe.addEventListener('click', supressClickEvent);
  });
}

export default {
  title: 'dxp/Quick Exit',
};

/**
 * "Show code" can't dynamically capture our output: the shared
 * squizStoryRenderer wraps it in lit's until() because main() is async
 * (per the DXP edge contract), but Storybook's web-components source
 * decorator reads the rendered container's innerHTML synchronously, before
 * that promise resolves -- so dynamic capture always sees an empty result.
 * Precomputing the real HTML here and handing it to Storybook explicitly
 * is the only reliable way to show it, at the cost of not live-updating
 * when Controls are tweaked. Computed via comp.main() directly (not the
 * withPageContent wrapper), so the source panel shows the real component
 * markup, not the docs-only page-simulation div around it.
 */
const defaultHtml = await squiz.markup(defaultArgs);

export const Default = {
  render: (args) => {
    requestAnimationFrame(suppressClick);
    return withPageContent(args);
  }     ,
  args: defaultArgs,
  argTypes: {
    label: { control: 'text' },
    message: { control: 'text' },
    exitUrl: { control: 'object', description: 'SquizLink object: { text, url, target? }. Note: activating the banner in this preview will really navigate the browser there.' },
    whatIsThisHref: { control: 'object', description: 'SquizLink object: { text, url, target? }.' },
    ariaLabel: { control: 'text' },
  },
  parameters: {
    docs: { source: { code: defaultHtml, language: 'html', type: 'code' } },
  },
};

const withWhatIsThisLinkHtml = await squiz.markup(withWhatIsThisLinkArgs);

export const WithWhatIsThisLink = {
  render: () => {
    requestAnimationFrame(suppressClick);
    return withPageContent(withWhatIsThisLinkArgs);
  },
  parameters: {
    docs: { source: { code: withWhatIsThisLinkHtml, language: 'html', type: 'code' } },
  },
};
